import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Button, Input, Modal, message, Alert } from 'antd';
import {
  createApplication,
  createOtherApp,
  gotCurrentApp,
  getAppDropdown,
} from 'redux/actions/appdropdown'
import { changeCommonValue } from 'redux/actions/common'
import Router from 'next/router'
import mixpanel from 'mixpanel-browser'
import _ from 'underscore'
// import ReCAPTCHA from 'react-google-recaptcha'
import ReactHtmlParser from 'react-html-parser'
// const recaptchaRef = React.createRef()
class CreateApp extends Component {
  constructor(props) {
    super(props)
    this.state = {
      appName: '',
      loading: false,
    }

    this.onChange = this.onChange.bind(this)
    this.createApp = this.createApp.bind(this)
    this.add = this.add.bind(this)
    this.cancel = this.cancel.bind(this)
    this._handleKeyPress = this._handleKeyPress.bind(this)
  }

  onChange(e) {
    this.setState({ [e.target.name]: e.target.value })
  }

  cancel = () => {
    this.props.cancelCreateApp()
    this.setState({ appName: '' })
  }

  add = (newApp) => {
    this.props.addNewApp ? this.props.addNewApp(newApp) : ''
  }

  createApp = async () => {
    let self = this
    if (!this.state.loading) {
      this.setState({ loading: true })
      let organizationId = self.props.orgId
        ? self.props.orgId
        : self.props.data.length === 1
        ? self.props.data[0].orgId
        : self.props.urlQuery.org
        ? self.props.urlQuery.org
        : self.props.userProfile.organization.length === 1 &&
          self.props.userProfile.organization[0]['$oid']

      // let captchaToken = await recaptchaRef.current.execute()
      if (_.isEmpty(self.props.currentApp)) {
        let res = await self.props.createApplication({
          name: self.state.appName,
          orgId: organizationId,
          notifyEmail: true,
          // captchaToken: captchaToken,
        })
        if (res.success) {
          if (this.props.data[0].apps.length === 1) {
            self.props.getAppDropdown()
            Router.push(
              `/integration?appId=${res.data.app['_id']}&parentType=overview`,
              `/app/${res.data.app['_id']}/overview`
            )
            return
          }
        }
        self.cancel()
        self.setState({ appName: '' })
        self.setState({ loading: false })
        if (res.success) {
          await self.add(res.data.app)
          if (self.props.pageCalled === 'sidebar') {
            if (self.props.urlQuery.setting) {
              Router.push(
                `/setting?setting=app_setting&org=${self.props.currentApp.orgId}&app=${self.props.currentApp['_id']}&app_tab=video_recording_setting`,
                `/settings/app/${self.props.currentApp.orgId}/${self.props.currentApp['_id']}/video_recording_setting`
              )
            } else {
              Router.push(
                `/integration?appId=${res.data.app['_id']}&parentType=sessionsList`,
                `/app/${res.data.app['_id']}/sessions/list`
              )
            }
          } else {
            Router.push(
              `/integration?parentType=settings&setting=app_setting&org=${res.data.app.orgId}&app=${res.data.app['_id']}&app_tab=video_recording_setting`,
              `/settings/app/${res.data.app.orgId}/${res.data.app['_id']}/video_recording_setting`
            )
          }
        } else {
          if (res.error.status == 403) {
            message.error(res.error.message)
          } else {
            // const reasonNoDashboardAccess = self.props.data.length === 1 ? !self.props.data[0]['dashboardAccess'] && self.props.data[0]['reasonNoDashboardAccess'] : false
            // const _message = reasonNoDashboardAccess && dashboardAccessMessages[reasonNoDashboardAccess]
            if(self.props.error.message && self.props.error.message.includes('suspicious behavior')) {
              self.props.changeCommonValue('isVisible_custom_popup', true)
            } else message.error(self.props.error.message)
          }
        }
        return
      }
      const res = await this.props.createOtherApp({
        name: this.state.appName,
        orgId: organizationId,
        notifyEmail: true,
        captchaToken: captchaToken,
      })
      if (res.success) {
        let orgName
        if (this.props.data && this.props.data.length) {
          this.props.data.map(function (value, i) {
            if (value.orgId == res.data.app.orgId) {
              orgName = value.name
            }
          })
        }

        let org_id = orgName + '_' + res.data.app.orgId
        self.cancel()
        message.success(res.data.message)
        self.add(res.data.app)
        self.setState({ appName: '' })
        self.setState({ loading: false })
        mixpanel?.identify(self.props.userProfile['_id'])
        mixpanel?.track('App Created', {
          app_name: self.state.appName,
          $email: self.props.userProfile.email,
          organization_id: org_id,
        })
        mixpanel?.people.increment('# of Apps', 1)
        if (this.props.urlQuery.parentType) {
          // Router.push(
          //   `/integration?parentType=${this.props.urlQuery.parentType}&appId=${res.data.app['_id']}`,
          //   `${process.env.REDIRECT_URL}/app/${res.data.app['_id']}/${
          //     arrObjParentType.includes(this.props.urlQuery.parentType)
          //       ? mappedObj[this.props.urlQuery.parentType]
          //       : this.props.urlQuery.parentType
          //   }`
          // )
          // Router.push(
          //   `/integration?parentType=integration&appId=${res.data.app['_id']}`,
          //   `/integration?appId=${res.data.app['_id']}`
          // ) // commented to remains on same app
        } else if (self.props.urlQuery.setting) {
          window.location.href =
            process.env.REDIRECT_URL +
            `/settings/app/${res.data.app.orgId}/${res.data.app['_id']}/video_recording_setting`
        }
      } else {
        self.setState({ loading: false })
        if (res.error.status == 403) {
          message.error(res.error.message)
        } else {
          if (self.props.error.message.includes('suspicious behavior')) {
            self.props.cancelCreateApp()
            self.props.changeCommonValue('isVisible_custom_popup', true)
          } else if(self.props.error.message.includes('upgrade your account')) {
            self.props.cancelCreateApp()
            self.props.changeCommonValue('isVisible_custom_popup', true, ReactHtmlParser(self.props.error.message))
          } else message.error(self.props.error.message)
        }
      }
      self.setState({ loading: false })
    }
  }

  _handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      this.createApp()
    }
  }

  render() {
    const { showCreateApp, cancelCreateApp } = this.props
    return (
      <Modal
        visible={showCreateApp}
        title={null}
        className='basic-info-modal'
        onCancel={cancelCreateApp}
        width={'460px'}
        centered
        footer={[
          <Button
            key='submit'
            type='primary'
            onClick={this.createApp}
            style={{ height: '35px', padding: '0 20px' }}
            disabled={this.state.loading || this.state.appName.length < 1}
            loading={this.state.loading}
          >
            OK
          </Button>,
        ]}
      >
        <div style={{ textAlign: 'left' }}>
          <h2>What's the name of your app?</h2>
          <Input
            size='large'
            name='appName'
            placeholder='Enter your app name'
            style={{
              marginBottom: '15px',
            }}
            value={this.state.appName}
            onChange={this.onChange}
            onKeyPress={this._handleKeyPress}
            autoFocus
          />
          <div className='create-org-notice'>
            <Alert
              message={`This app will be part of organization - ${this.props.orgName}. Managers will have access to by default and you can invite other members to join the app.`}
              showIcon
            />
          </div>
          {/* <ReCAPTCHA
            ref={recaptchaRef}
            size='invisible'
            sitekey={process.env.SITE_KEY}
          /> */}
        </div>
        <style>{`
                .basic-info-modal h2{
                  text-transform: none;
                  font-size: 1.2rem;
                  margin: 0 0 15px;
                }
                .basic-info-modal .ant-modal-footer{
                    text-align: center;
                    border: 0;
                    padding: 0 24px 24px
                }
                .create-org-notice .ant-alert-info{
                  border-color: #5D97FF;
                  background-color: rgba(93, 151, 255, 0.1);
                  color: #5D97FF;
                  line-height: normal;
                }
                .create-org-notice .ant-alert-info .anticon{
                  color: #5D97FF;
                }
            `}</style>
      </Modal>
    )
  }
}

function mapStateToProps(state) {
  return {
    error: state.errorReducer,
    urlQuery: state.urlReducer,
    data: state.applicationReducer,
    userProfile: state.profileReducer,
    currentApp: state.currentAppReducer,
    csrf: state.csrfReducer,
    orgName: state.currentOrgReducer.orgName,
    orgId: state.currentOrgReducer.orgId,
  }
}

export default connect(mapStateToProps, {
  createApplication,
  createOtherApp,
  gotCurrentApp,
  getAppDropdown,
  changeCommonValue
})(CreateApp)
